css:
/* NEON//GRID 8 by Vex (round 6: on the v1.5 tokens, no magic numbers). "The terminal at 3 a.m."
   One idea: a quiet black-glass terminal looking out at a rain-slick city. Light only where it means something.
   Signature: thin cyan corner brackets on the surface that has focus + one straight neon tube under the top bar.
   Night: void #05060B, glass #0B0F1A, ink #E6F1FF, cyan #22E4F5, magenta #FF2BD6, dim #8A98B3, amber #FFB547.
   Day ("dawn grid"): paper #EEF2F7, ink #0E1424, cyan #0077A8, magenta #C2179E, white glass.
   Type: body Figtree 15px, mono Share Tech Mono for chrome and meta, VT323 for big display only. */

:root {
  --mari-tokens-version: 1;
  --neon-font-mono: "NeonGrid Mono", "Share Tech Mono", ui-monospace, Menlo, Consolas, monospace;
  --neon-font-display: "NeonGrid VT323", "NeonGrid Mono", ui-monospace, monospace;
  --neon-font-body: "Figtree Variable", "Figtree", system-ui, -apple-system, "Segoe UI", sans-serif;
  --mari-font-ui: var(--neon-font-body);
  --mari-font-chat: var(--neon-font-body);
  --mari-font-heading: var(--neon-font-display);
  --radius: 0.25rem;
  --mari-cursor: url("theme:cursor.png") 1 1, auto;
  --mari-top-bar-plate-radius: 3px;
  --marinara-theme-accent-pulse: disabled;
  /* v1.4 slots */
  --mari-focus-frame: var(--hud) 32 / 28px stretch;
  --mari-focus-frame-outset: 7px;
  --mari-ambient-placement: behind-cards;
  --mari-ambient-mask: var(--mari-gutter-mask);
  --mari-gutter-clear: 23rem;
  --mari-toast-font-size: 14px;
  --mari-min-ui-text: 11.5px;
  --mari-home-shortcut-size: 0.95rem;
  --mari-home-shortcut-desc-size: 0.84rem;
  --mari-chat-wash: none;
  /* v1.5 long replies: one column for messages and the message box (about 75 characters a line) */
  --mari-chat-column: 33rem;
  --mari-message-measure: 56ch;
  --mari-chat-line-height: 1.68;
  --mari-paragraph-gap: 0.8em;
  --mari-pinned-speaker: on;
  --mari-pinned-speaker-bg: var(--neon-head);
  --mari-phone-avatar: hidden;
  --mari-chat-row-art-opacity: 0;
  --mari-vn-fade: 2.25rem;
}

/* ═════ NIGHT ═════ */
:root, :root[data-theme="dark"] {
  --nc: #22e4f5;           /* cyan: primary, assistant, focus */
  --nm: #ff2bd6;           /* magenta: user, accent */
  --na: #ffb547;           /* amber: game, warnings */
  --ink: #e6f1ff;
  --dim: #8a98b3;
  --faint: #7d8aa5;
  --void: #05060b;
  --glass: rgb(9 12 22 / 0.84);
  --glass-strong: rgb(7 9 17 / 0.94);
  --line: rgb(34 228 245 / 0.16);
  --line-strong: rgb(34 228 245 / 0.42);
  --hud: url("theme:hud-corners.png");

  --background: #05060b;
  --foreground: var(--ink);
  --card: var(--glass);
  --card-foreground: var(--ink);
  --popover: #0a0e19;
  --popover-foreground: var(--ink);
  --primary: #22e4f5;
  --primary-foreground: #031014;
  --secondary: #111726;
  --secondary-foreground: var(--ink);
  --muted: #111726;
  --muted-foreground: #9aa7bf;
  --accent: #121a2b;
  --accent-foreground: var(--ink);
  --destructive: #ff4d6d;
  --destructive-foreground: #fff;
  --border: var(--line);
  --input: rgb(34 228 245 / 0.22);
  --ring: var(--nc);
  --sidebar: rgb(6 8 15 / 0.9);
  --sidebar-foreground: var(--ink);
  --sidebar-border: var(--line);
  --sidebar-accent: rgb(34 228 245 / 0.08);
  --sidebar-accent-foreground: #fff;

  --ov-line: var(--line);
  --ov-text: var(--ink);
  --ov-muted: #9aa7bf;
  --ov-dim: #6f7c95;
  --ov-accent: var(--nc);
  --ov-hover: rgb(34 228 245 / 0.07);
  --ov-active-bg: rgb(34 228 245 / 0.12);
  --ov-mode-conversation: var(--nc);
  --ov-mode-roleplay: var(--nm);
  --ov-mode-game: var(--na);
  --mari-mode-conversation: var(--nc);
  --mari-mode-roleplay: var(--nm);
  --mari-mode-game: var(--na);
  --mari-home-pink: var(--nm);
  --mari-home-violet: #9b7bff;
  --mari-selected-tint: var(--nc);
  --mari-status-online: #3dffa8;
  --mari-gauge-ok: #3dffa8;
  --mari-gauge-warn: var(--na);
  --mari-gauge-danger: #ff4d6d;
  --mari-game-combat: #ff4d6d;
  --mari-game-combat-text: #0a0006;
  --mari-scrim: rgb(2 3 8 / 0.72);
  --mari-user-avatar-placeholder: linear-gradient(135deg, #2a0f2c, #10142a);
  --mari-art-saturation-1: 30%; --mari-art-lightness-1: 13%;
  --mari-art-saturation-2: 40%; --mari-art-lightness-2: 6%;
  --mari-focus-ring-color: var(--nc);

  --mari-app-backdrop-layers:
    linear-gradient(180deg, rgb(5 6 11 / 0.2) 0%, rgb(5 6 11 / 0) 50%),
    url("theme:bd-night.webp") center bottom / cover no-repeat;
  --mari-ambient: url("theme:rain.png") 0 0 / 512px 512px repeat;
  --mari-ambient-opacity: 0.9;
  --mari-ambient-animation: neon-rain 1.6s linear infinite;
  --mari-home-wash: rgb(5 6 11 / 0.35);
  --mari-home-art: none;
  --mari-page-veil: rgb(5 6 11 / 0.82);
  --mari-top-bar-bg: url("theme:topbar-strip.webp") left bottom / 100% 100% no-repeat, #05060b;
  --mari-top-bar-plate: rgb(5 6 11 / 0.88);

  --mari-chat-font-size: 15.5px;
  --mari-text-outline: 0;
  --mari-dialogue-color: #86e6f2;
  --mari-msg-head-rule: 1px solid rgb(34 228 245 / 0.12);
  --mari-composer-placeholder: "> transmit_";
  --mari-chat-radius: 3px;
  --mari-chat-text: var(--ink);
  --mari-chat-bg: var(--glass);
  --mari-chat-border: var(--line);
  --mari-chat-input-bg: rgb(6 8 15 / 0.9);
  --mari-chrome-accent: var(--nc);
  --mari-dialogue-weight: 500;
  --mari-window-bg: var(--glass-strong);
  --mari-window-border: var(--line-strong);
  --mari-window-radius: 3px;
  --mari-window-shadow: 0 24px 60px rgb(0 0 0 / 0.6);
  --mari-stage-empty-bg:
    radial-gradient(60% 50% at 0% 70%, rgb(255 181 71 / 0.16), transparent 70%),
    radial-gradient(50% 40% at 100% 40%, rgb(34 228 245 / 0.12), transparent 70%),
    linear-gradient(180deg, #07080c, #12100c);

  --mari-home-widget-border: var(--line);
  --mari-home-widget-border-width: 1px;
  --mari-home-widget-radius: 3px;
  --mari-home-widget-bg: var(--glass);
  --mari-home-widget-title-font: var(--neon-font-display);
  --mari-home-widget-title-size: 1.9rem;
  --mari-home-widget-title-color: var(--ink);
  --mari-home-widget-eyebrow-color: var(--nc);
  --mari-home-widget-eyebrow-size: 0.8rem;
  --mari-home-widget-text-size: 0.95rem;
  --mari-home-widget-muted: #9aa7bf;

  --marinara-app-accent-solid: var(--nc);
  --marinara-app-accent-gradient: linear-gradient(90deg, var(--nc), var(--nm));
  --mari-icon-send: url("theme:send.svg");
  --mari-user-avatar-image: url("theme:user-tile.svg");

  /* v1.4: the formerly hard-coded bits */
  --mari-message-time: #8d9ab4;
  --mari-chrome-accent: var(--nc);
  --mari-chrome-muted: #9aa7bf;
  --mari-resource-accent: var(--nc);
  --mari-resource-characters: var(--nc);
  --mari-resource-personas: var(--nm);
  --mari-resource-lorebooks: var(--na);
  --mari-resource-presets: #a993ff;
  --mari-resource-connections: #3dffa8;
  --mari-resource-agents: var(--nc);
  --mari-resource-settings: #9aa7bf;
  --mari-resource-backgrounds: var(--nm);
  --mari-resource-browser: var(--nc);
  --mari-ctrlk-conversation: var(--nc);
  --mari-ctrlk-roleplay: var(--nm);
  --mari-ctrlk-game: var(--na);
  --mari-game-combat-bg: rgb(255 77 109 / 0.14);
  --mari-game-combat-bg-hover: rgb(255 77 109 / 0.26);
  --mari-game-combat-border: rgb(255 77 109 / 0.7);
  --mari-top-bar-plate-active: color-mix(in srgb, rgb(5 6 11 / 0.92) 78%, var(--nc));
  --mari-chat-header-bg: linear-gradient(180deg, #05060b 0%, #05060b 78%, rgb(5 6 11 / 0));
  --mari-home-widget-glow: radial-gradient(60% 100% at 0% 0%, rgb(34 228 245 / 0.10), transparent 70%);
  --mari-lore-constant: var(--nc);
  --mari-lore-selective: var(--nm);
  --mari-lore-normal: #6f7c95;
  --neon-em: #d4c7ff;          /* inner voice / italics */
  --mari-message-actions: #7f8fae;
  --mari-swipe-counter: #9aa7bf;
  --mari-card-art-placeholder: url("theme:hex.png") 0 0 / 54px 62px, linear-gradient(180deg, #0c1222, #070a13);
  --neon-fade: #05060b;
  --neon-head: #0a0d17;
}

/* ═════ DAY: dawn grid ═════ */
:root[data-theme="light"] {
  --nc: #0077a8;
  --nm: #c2179e;
  --na: #a35f00;
  --ink: #0e1424;
  --dim: #4a5670;
  --faint: #6b7690;
  --glass: rgb(255 255 255 / 0.86);
  --glass-strong: rgb(255 255 255 / 0.96);
  --line: rgb(14 20 36 / 0.12);
  --line-strong: rgb(0 119 168 / 0.45);

  --background: #eef2f7;
  --foreground: var(--ink);
  --card: var(--glass);
  --card-foreground: var(--ink);
  --popover: #fbfcfe;
  --popover-foreground: var(--ink);
  --primary: #0077a8;
  --primary-foreground: #fff;
  --secondary: #e4eaf2;
  --secondary-foreground: var(--ink);
  --muted: #e4eaf2;
  --muted-foreground: #4a5670;
  --accent: #dfe7f1;
  --accent-foreground: var(--ink);
  --border: var(--line);
  --input: rgb(14 20 36 / 0.18);
  --sidebar: rgb(246 248 252 / 0.92);
  --sidebar-foreground: var(--ink);
  --sidebar-border: var(--line);
  --sidebar-accent: rgb(0 119 168 / 0.08);
  --sidebar-accent-foreground: var(--ink);
  --ov-line: var(--line);
  --ov-text: var(--ink);
  --ov-muted: #4a5670;
  --ov-dim: #6b7690;
  --ov-hover: rgb(0 119 168 / 0.06);
  --ov-active-bg: rgb(0 119 168 / 0.1);
  --mari-status-online: #007a4e;
  --mari-gauge-ok: #00a86b;
  --mari-scrim: rgb(14 20 36 / 0.35);
  --mari-user-avatar-placeholder: linear-gradient(135deg, #f6d9ee, #d8e9f4);
  --mari-art-saturation-1: 45%; --mari-art-lightness-1: 86%;
  --mari-art-saturation-2: 45%; --mari-art-lightness-2: 76%;

  --mari-app-backdrop-layers:
    linear-gradient(180deg, rgb(238 242 247 / 0.3) 0%, rgb(238 242 247 / 0) 50%),
    url("theme:bd-day.webp") center bottom / cover no-repeat;
  --mari-ambient: none;
  --mari-home-wash: rgb(238 242 247 / 0.4);
  --mari-page-veil: rgb(238 242 247 / 0.88);
  --mari-top-bar-bg: url("theme:topbar-strip-day.webp") left bottom / auto 100% repeat-x, #f4f7fb;
  --mari-top-bar-plate: rgb(244 247 251 / 0.92);
  --mari-dialogue-color: #005f87;
  --mari-msg-head-rule: 1px solid rgb(14 20 36 / 0.1);
  --mari-chat-input-bg: rgb(255 255 255 / 0.94);
  --mari-window-shadow: 0 24px 60px rgb(14 20 36 / 0.18);
  --mari-stage-empty-bg:
    radial-gradient(60% 50% at 0% 70%, rgb(255 181 71 / 0.25), transparent 70%),
    linear-gradient(180deg, #f4efe6, #e8e2d6);
  --mari-home-widget-muted: #4a5670;
  --mari-icon-send: url("theme:send-day.svg");
  --mari-user-avatar-image: url("theme:user-tile-day.svg");
  --mari-message-time: #56627c;
  --mari-chrome-muted: #4a5670;
  --mari-resource-presets: #6a4fd0;
  --mari-resource-connections: #00875a;
  --mari-resource-settings: #4a5670;
  --mari-game-combat-bg: rgb(200 30 70 / 0.08);
  --mari-game-combat-bg-hover: rgb(200 30 70 / 0.16);
  --mari-game-combat-border: rgb(200 30 70 / 0.6);
  --mari-top-bar-plate-active: color-mix(in srgb, #ffffff 82%, var(--nc));
  --mari-chat-header-bg: linear-gradient(180deg, #f2f5f9 0%, #f2f5f9 78%, rgb(242 245 249 / 0));
  --mari-home-widget-glow: radial-gradient(60% 100% at 0% 0%, rgb(0 119 168 / 0.08), transparent 70%);
  --mari-lore-normal: #8a95ab;
  --neon-em: #5b3fa8;
  --mari-message-actions: #56627c;
  --mari-swipe-counter: #4a5670;
  --mari-card-art-placeholder: linear-gradient(180deg, #ffffff, #e6edf5);
  --neon-fade: #eef2f7;
  --neon-head: #ffffff;
}

@keyframes neon-rain { to { background-position: 90px 512px; } }

/* ═════ Global type ═════ */
:is(h1, h2, h3) { letter-spacing: 0.01em; }
::selection { background: rgb(34 228 245 / 0.3); color: #fff; }
:root[data-theme="light"] ::selection { background: rgb(0 119 168 / 0.2); color: var(--ink); }
:root[data-theme="dark"] { scrollbar-color: rgb(34 228 245 / 0.25) transparent; }

/* ═════ Top bar (restyle only) ═════ */
[data-component="TopBar"] { border-bottom: 0; box-shadow: 0 8px 24px -12px rgb(0 0 0 / 0.8); }
:root[data-theme="light"] [data-component="TopBar"] { box-shadow: 0 6px 18px -12px rgb(14 20 36 / 0.25); }
[data-component="TopBar"] :is(.ov-tab, button, a) { font-family: var(--neon-font-mono); letter-spacing: 0.03em; }
[data-component="TopBar"] .ov-tab.is-on {
  background: rgb(34 228 245 / 0.12);
  box-shadow: inset 0 0 0 1px rgb(34 228 245 / 0.45);
  border-radius: 3px;
  color: #fff;
}
:root[data-theme="light"] [data-component="TopBar"] .ov-tab.is-on { background: #fff; box-shadow: inset 0 0 0 1px rgb(0 119 168 / 0.45); color: var(--ink); }

/* ═════ Sidebars: dark glass + hex grid, one hairline ═════ */
[data-component="ChatSidebarPanel"],
[data-component="RightPanelDesktop"],
[data-component="RightPanelMobile"] {
  background-color: var(--sidebar);
  background-image: url("theme:hex.png");
  background-size: 72px 83px;
  backdrop-filter: blur(14px) saturate(1.2);
}
[data-component="ChatSidebarPanel"] { border-right: 1px solid var(--line); }
[data-component="RightPanelDesktop"] { border-left: 1px solid var(--line); }
:root[data-theme="light"] :is([data-component="ChatSidebarPanel"], [data-component="RightPanelDesktop"], [data-component="RightPanelMobile"]) { background-image: none; }

[data-chat-row] { border-radius: 3px; }
[data-chat-row] .h-7.w-7 > div {
  border-radius: 3px;
  background: transparent;
  box-shadow: inset 0 0 0 1px var(--line-strong);
  color: var(--nc);
  font-family: var(--neon-font-mono);
  font-weight: 400;
  font-size: 0.75rem;
}
[data-chat-row] img.object-cover { display: none; }
[data-chat-row][data-selected="true"] {
  background: linear-gradient(90deg, rgb(34 228 245 / 0.14), rgb(34 228 245 / 0.03));
  box-shadow: inset 2px 0 0 var(--nc);
}
:root[data-theme="light"] [data-chat-row][data-selected="true"] { background: linear-gradient(90deg, rgb(0 119 168 / 0.12), rgb(0 119 168 / 0.02)); }

/* ═════ Messages: glass cards, the newest reply gets the brackets ═════ */
.mari-rp-bubble {
  border-radius: 3px !important;
  background: var(--glass) !important;
  box-shadow: 0 10px 30px -14px rgb(0 0 0 / 0.7) !important;
  --tw-ring-color: var(--line);
  backdrop-filter: blur(6px);
}
.mari-rp-bubble--user {
  background: linear-gradient(90deg, rgb(255 43 214 / 0.10), rgb(255 43 214 / 0) 60%), var(--glass) !important;
  box-shadow: inset 2px 0 0 rgb(255 43 214 / 0.7), 0 10px 30px -14px rgb(0 0 0 / 0.7) !important;
}
:root[data-theme="light"] .mari-rp-bubble { box-shadow: 0 8px 24px -14px rgb(14 20 36 / 0.3) !important; }
:root[data-theme="light"] .mari-rp-bubble--user {
  background: linear-gradient(90deg, rgb(194 23 158 / 0.07), rgb(194 23 158 / 0) 60%), var(--glass) !important;
  box-shadow: inset 2px 0 0 rgb(194 23 158 / 0.7), 0 8px 24px -14px rgb(14 20 36 / 0.3) !important;
}
.mari-message-content { line-height: 1.62; color: var(--ink); }
[data-mari-part="message"] [data-mari-part="header"] .mari-message-name {
  font-family: var(--neon-font-mono);
  font-size: 0.82rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-weight: 400;
  color: var(--nc);
}
[data-mari-part="message"][data-message-role="user"] [data-mari-part="header"] .mari-message-name { color: var(--nm); }
[data-mari-part="message"] [data-mari-part="header"] > span:nth-child(2) {
  font-family: var(--neon-font-mono);
  font-size: 0.72rem;
  color: var(--faint);
}
/* message number as a terminal index after the time */
[data-mari-part="message"] [data-mari-part="header"] .ov-rpmsg__grow::before {
  counter-reset: msg var(--mari-msg-index, 0);
  content: "#" counter(msg, decimal-leading-zero);
  font-family: var(--neon-font-mono);
  font-size: 0.72rem;
  color: var(--faint);
  margin-left: 0.5rem;
}

/* avatars: square tiles, hairline frame, no gradient candy */
[data-mari-part="message"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"] {
  border-radius: 3px !important;
  --tw-ring-color: rgb(34 228 245 / 0.35) !important;
  --tw-ring-shadow: 0 0 0 1px var(--tw-ring-color) !important;
  box-shadow: 0 0 0 1px rgb(34 228 245 / 0.35) !important;
  background: #0b1020;
  color: var(--nc);
  animation: none !important;
  filter: none !important;
}
[data-mari-part="message"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"] svg { color: inherit; }
[data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"] { box-shadow: 0 0 0 1px rgb(255 43 214 / 0.45) !important; color: var(--nm); background: var(--mari-user-avatar-placeholder); }
:root[data-theme="light"] [data-mari-part="message"] [data-mari-part="avatar"] > [data-mari-part="avatar-placeholder"] { background: #fff; box-shadow: 0 0 0 1px rgb(0 119 168 / 0.4) !important; }

/* THE signature: corner brackets on whatever has focus come from --mari-focus-frame (v1.4 slot). */
:root[data-theme="light"] { --hud: url("theme:hud-corners-day.png"); }
[data-mari-part="message"][data-streaming] .mari-message-content::after {
  content: "\2588"; margin-left: 0.15em; color: var(--nc); animation: neon-blink 0.7s steps(1) infinite;
}
@keyframes neon-blink { 50% { opacity: 0; } }

/* message tools: quiet until hover */
.ov-rpf__btn { border-radius: 3px; }

/* conversation: a calm log column on glass */
[data-chat-mode="conversation"]:not([data-mari-part="chat-header"]) {
  background: linear-gradient(90deg, rgb(5 6 11 / 0.88) 0%, rgb(5 6 11 / 0.84) 55%, rgb(5 6 11 / 0.4) 100%) !important;
}
:root[data-theme="light"] [data-chat-mode="conversation"]:not([data-mari-part="chat-header"]) {
  background: linear-gradient(90deg, rgb(246 248 252 / 0.93) 0%, rgb(246 248 252 / 0.9) 55%, rgb(246 248 252 / 0.45) 100%) !important;
}
[data-chat-mode="conversation"] [data-mari-part="message"] {
  border-radius: 3px;
  box-shadow: inset 2px 0 0 rgb(34 228 245 / 0.35);
}
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] { box-shadow: inset 2px 0 0 rgb(255 43 214 / 0.55); }

/* ═════ Composer ═════ */
[data-mari-part="composer"] .mari-chat-input-box {
  border-radius: 3px;
  border-color: var(--line-strong);
  background: var(--mari-chat-input-bg);
  box-shadow: 0 0 0 1px rgb(34 228 245 / 0.08), 0 12px 32px -12px rgb(0 0 0 / 0.8);
}
[data-mari-part="composer"] :is(textarea, input) { font-family: var(--neon-font-mono); font-size: 15px; }
[data-mari-part="composer"] textarea { caret-color: var(--nm); }
:root[data-theme="light"] [data-mari-part="composer"] .mari-chat-input-box { box-shadow: 0 10px 28px -14px rgb(14 20 36 / 0.3); }

/* ═════ Panels: dialogs, menus, Ctrl+K, toasts, drawers. Same glass, same brackets ═════ */
:is([role="dialog"], [cmdk-root], .mari-window, .mari-drawer) {
  border-radius: 3px;
}
:is([role="menu"], [role="listbox"], [data-radix-popper-content-wrapper] > *) {
  border-radius: 3px;
  border-color: var(--line-strong);
}
[data-sonner-toast] {
  border-radius: 3px !important;
  border: 1px solid var(--line-strong) !important;
  background: var(--glass-strong) !important;
  color: var(--ink) !important;
  font-family: var(--neon-font-body);
  box-shadow: inset 2px 0 0 var(--nc), 0 16px 40px -12px rgb(0 0 0 / 0.6) !important;
}
[data-component="GlobalOmnibar"] > [role="dialog"] {
  border-color: var(--line-strong);
  border-radius: 3px;
  background: var(--glass-strong);
  backdrop-filter: blur(18px);
}
[data-component="GlobalOmnibar"] > [role="dialog"] > div.pointer-events-none.absolute {
  background: radial-gradient(90% 100% at 10% 0%, rgb(34 228 245 / 0.10), transparent 60%);
}
[data-omnibar-scope-chip] { font-family: var(--neon-font-mono); letter-spacing: 0.04em; }
[cmdk-input] { font-family: var(--neon-font-mono); }

/* pills become HUD chips: one radius everywhere */
button.rounded-full:not([role="switch"]):not(:has(> img)):not(.overflow-hidden),
:is(button, a)[class*="pill"], .ovm-chats-home { border-radius: 3px !important; }

/* ═════ Home ═════ */
[data-mari-part="home-widget"] { backdrop-filter: blur(10px); }
[data-mari-part="home-widget"] [data-mari-part="home-widget-eyebrow"] { font-family: var(--neon-font-mono); letter-spacing: 0.16em; }
[data-mari-part="home-widget"] [data-mari-part="home-widget-title"] { line-height: 1; }
.ov-recent__avatar {
  border-radius: 3px !important;
  background: transparent !important;
  box-shadow: inset 0 0 0 1px var(--line-strong);
  color: var(--nc) !important;
  font-family: var(--neon-font-mono);
  font-weight: 400;
}
[data-component="RecentChats"] > li > button { padding-block: 0.55rem; border-radius: 3px; }
.ov-recent__mode { font-family: var(--neon-font-mono); border-radius: 3px; letter-spacing: 0.04em; }
.ov-recent__time { font-family: var(--neon-font-mono); color: var(--faint); }

/* small headings stay mono: VT323 only where it is big */
:is([data-component="ChatSidebarPanel"], [data-component="RightPanelMobile"]) :is(h1, h2, h3) { font-family: var(--neon-font-mono); letter-spacing: 0.06em; font-weight: 400; }

/* ═════ Full pages ═════ */
[data-component="OverhaulSettingsPage"] :is(h1, h2) { font-family: var(--neon-font-display); font-weight: 400; }

/* game: amber emergency light over the same city (stand-in until the relay-corridor art lands) */
:root[data-theme][data-chat-open-mode="game"] {
  --mari-app-backdrop-layers:
    linear-gradient(180deg, rgb(5 6 11 / 0.15), rgb(5 6 11 / 0.35)),
    url("theme:bd-game.webp") center / cover no-repeat;
  --mari-stage-empty-bg: transparent;
  --mari-ambient: none;
}
/* by day the corridor stays a scene, just with the lights up a little */
:root[data-theme="light"][data-chat-open-mode="game"] {
  --mari-app-backdrop-layers:
    linear-gradient(180deg, rgb(238 242 247 / 0.18), rgb(238 242 247 / 0.05)),
    url("theme:bd-game.webp") center / cover no-repeat;
}
/* game stage: let the backdrop through */
[data-mari-part="stage-empty"] { background: var(--mari-stage-empty-bg); }

/* ═════ Reduce motion / high contrast ═════ */
@media (prefers-reduced-motion: reduce) {
  [data-mari-part="message"][data-streaming] .mari-message-content::after { animation: none; }
}
:root[data-mari-contrast="more"] .mari-rp-bubble { backdrop-filter: none; }

/* ═════ Long replies: a reading column, three voices, a sticky speaker line ═════ */
/* the card stays a terminal window, but the column is capped at about 70-78 characters */
/* column: --mari-chat-column; measure: --mari-message-measure; leading: --mari-chat-line-height */
.mari-rp-bubble .mari-message-content { letter-spacing: 0.003em; }
/* dialogue: cyan-tinted ink, medium weight (bold walls are gone): --mari-dialogue-weight */
/* markdown bold keeps real bold in body ink */
.mari-message-content strong:not([style]) { font-weight: 700; color: var(--ink); }
/* italics: the inner voice */
.mari-message-content em { color: var(--neon-em); }
.mari-message-content strong[style*="dialogue"] em, .mari-message-content em strong { color: inherit; }
/* lists: mono cyan markers, a little air */
.mari-message-content :is(ol, ul) { margin: 0.4em 0 0; padding-left: 1.6em; }
.mari-message-content li { margin: 0.25em 0; padding-left: 0.2em; }
.mari-message-content li::marker { color: var(--nc); font-family: var(--neon-font-mono); font-size: 0.92em; }
/* the scene break: one tube, like the top bar, with a // in the middle */
.mari-message-content hr {
  position: relative; overflow: visible; height: 1px; border: 0; margin: 1.3em 0 1.1em;
  background: linear-gradient(90deg, transparent, rgb(34 228 245 / 0.55) 18%, rgb(255 43 214 / 0.55) 82%, transparent);
}
.mari-message-content hr::after {
  content: "//"; position: absolute; left: 50%; top: 50%; transform: translate(-50%, -54%);
  padding: 0 0.6em; background: var(--glass-strong); color: var(--faint);
  font-family: var(--neon-font-mono); font-size: 0.78rem; line-height: 1; letter-spacing: 0.1em;
}
:root[data-theme="light"] .mari-message-content hr { background: linear-gradient(90deg, transparent, rgb(0 119 168 / 0.5) 18%, rgb(194 23 158 / 0.5) 82%, transparent); }
:root[data-theme="light"] .mari-message-content hr::after { background: #fff; }
/* the speaker line stays pinned while a long card scrolls past: --mari-pinned-speaker (v1.5).
   The theme only dresses it: an opaque terminal title bar with one hairline. */
.mari-rp-bubble [data-mari-part="header"][data-placement="inside"] {
  margin-top: -0.75rem; margin-bottom: 0.55rem; padding-block: 0.7rem 0.5rem;
  border-bottom: 1px solid var(--line);
}

/* the composer sits on a short fade, so cards never show through under it */
[data-roleplay-chat-column="true"]::before {
  content: ""; position: absolute; z-index: -1; pointer-events: none;
  left: -50vw; right: -50vw; bottom: 0; height: calc(100% + 1.25rem);
  background: linear-gradient(180deg, transparent, var(--neon-fade) 1.25rem);
}
/* v1.5 lets dialogue, italics and links paint their own colour; bold and list markers still need it */
.mari-message-content :is(strong, li::marker) { -webkit-text-fill-color: currentColor; }

/* Home shortcuts: the stock colour icons become one line-icon set in the theme colour */
img.mari-home-widget-shortcut__icon[src*="/documentation."] { content: var(--ico-documentation); }
img.mari-home-widget-shortcut__icon[src*="/tutorial."] { content: var(--ico-tutorial); }
img.mari-home-widget-shortcut__icon[src*="/faq."] { content: var(--ico-faq); }
img.mari-home-widget-shortcut__icon[src*="/discord."] { content: var(--ico-discord); }
img.mari-home-widget-shortcut__icon[src*="/kofi."] { content: var(--ico-kofi); }
img.mari-home-widget-shortcut__icon[src*="/credits."] { content: var(--ico-credits); }
:root, :root[data-theme="dark"] { --ico-documentation: url("theme:ico-documentation-n.svg"); --ico-tutorial: url("theme:ico-tutorial-n.svg"); --ico-faq: url("theme:ico-faq-n.svg"); --ico-discord: url("theme:ico-discord-n.svg"); --ico-kofi: url("theme:ico-kofi-n.svg"); --ico-credits: url("theme:ico-credits-n.svg"); }
:root[data-theme="light"] { --ico-documentation: url("theme:ico-documentation-d.svg"); --ico-tutorial: url("theme:ico-tutorial-d.svg"); --ico-faq: url("theme:ico-faq-d.svg"); --ico-discord: url("theme:ico-discord-d.svg"); --ico-kofi: url("theme:ico-kofi-d.svg"); --ico-credits: url("theme:ico-credits-d.svg"); }

/* ═════ Conversation: square mono tiles, a terminal date stamp ═════ */
[data-chat-mode="conversation"] [data-mari-part="avatar"] > button { border-radius: 3px !important; box-shadow: inset 0 0 0 1px var(--line-strong); background: #0b1020; }
[data-chat-mode="conversation"] [data-mari-part="avatar"] > button > div:not(:has(img)) { color: var(--nc); font-family: var(--neon-font-mono); font-weight: 400; }
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] > button:not(:has(img)) { background: var(--mari-user-avatar-image) center / cover no-repeat; box-shadow: inset 0 0 0 1px rgb(255 43 214 / 0.45); }
[data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] > button:not(:has(img)) > div { visibility: hidden; }
:root[data-theme="light"] [data-chat-mode="conversation"] [data-mari-part="avatar"] > button { background: #fff; }
:root[data-theme="light"] [data-chat-mode="conversation"] [data-mari-part="message"][data-message-role="user"] [data-mari-part="avatar"] > button:not(:has(img)) { background: var(--mari-user-avatar-image) center / cover no-repeat; box-shadow: inset 0 0 0 1px rgb(194 23 158 / 0.45); }
[data-chat-mode="conversation"] .mari-conversation-transcript-chrome-text.font-semibold { font-family: var(--neon-font-mono); font-weight: 400; letter-spacing: 0.14em; text-transform: uppercase; color: var(--nc); }
[data-chat-mode="conversation"] .mari-conversation-transcript-chrome-text.font-semibold::before { content: "// "; color: var(--faint); }
[data-mari-part="time"] { font-family: var(--neon-font-mono); }

/* ═════ Library: empty portraits are dark glass with the hex grid, not random tints ═════ */
.mari-avatar-placeholder {
  background: url("theme:hex.png") 0 0 / 54px 62px, linear-gradient(180deg, #0c1222, #070a13) !important;
  box-shadow: inset 0 0 0 1px var(--line-strong);
  color: var(--nc);
}
.mari-avatar-placeholder--persona { box-shadow: inset 0 0 0 1px rgb(255 43 214 / 0.45); color: var(--nm); }
.mari-avatar-placeholder svg { color: inherit; opacity: 0.8; }
:root[data-theme="light"] .mari-avatar-placeholder { background: linear-gradient(180deg, #ffffff, #e9eef5) !important; }
/* conversation header: a solid strip with a mono identity chip, so the log never runs behind the chip */
[data-mari-part="chat-header"] { background: var(--mari-chat-header-bg) !important; padding-bottom: 0.9rem; }
[data-mari-part="chat-header"] .marinara-chat-toolbar-button { border-radius: 3px; border-color: var(--line-strong); background: var(--glass-strong); }
[data-mari-part="chat-header"] .marinara-chat-toolbar-button .rounded-full:not(.absolute) { border-radius: 2px; color: var(--nc); font-family: var(--neon-font-mono); font-weight: 400; background: transparent; }
[data-mari-part="chat-header"] .marinara-chat-toolbar-button .truncate.font-semibold { font-family: var(--neon-font-mono); font-weight: 400; letter-spacing: 0.06em; text-transform: uppercase; color: var(--nc); }

/* phone and narrow layouts put the name above the card: that line pins too */
.mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] {
  /* the app publishes the transcript's top padding (as a negative offset) for the pinned speaker */
  position: sticky; top: var(--mari-pinned-speaker-auto-top, -52px); z-index: 2; padding-block: 0.35rem 0.4rem;
  background: linear-gradient(180deg, var(--neon-fade) 75%, transparent);
}
/* where the browser can tell, the plate only appears while the name line is actually pinned */
@supports (container-type: scroll-state) {
  .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"] { container-type: scroll-state; background: none; }
  .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"]::before {
    content: ""; position: absolute; z-index: -1; inset: 0 -100vw; pointer-events: none;
  }
  @container scroll-state(stuck: top) {
    .mari-roleplay-message-body > [data-mari-part="header"][data-placement="outside"]::before {
      background: linear-gradient(180deg, var(--neon-fade) 75%, transparent);
    }
  }
}
/* on phones the transcript's top padding is not under anything, so pin right under the top bar */

/* portrait screens (phones, iPad Mini upright) get the portrait plates: calm sky above, the city low */
@media (max-aspect-ratio: 4/5) {
  :root, :root[data-theme="dark"] {
    --mari-app-backdrop-layers: url("theme:bd-night-p.webp") center bottom / cover no-repeat;
  }
  :root[data-theme="light"] {
    --mari-app-backdrop-layers: url("theme:bd-day-p.webp") center bottom / cover no-repeat;
  }
}
/* Library cards use --mari-card-art-placeholder; the game party rail has no token yet */
.ov-rail__portrait.is-empty, .ov-rail__portrait-empty {
  background: url("theme:hex.png") 0 0 / 54px 62px, linear-gradient(180deg, #0c1222, #070a13) !important;
  box-shadow: inset 0 0 0 1px var(--line-strong);
  color: var(--nc) !important;
}
:root[data-theme="light"] :is(.ov-rail__portrait.is-empty, .ov-rail__portrait-empty) {
  background: linear-gradient(180deg, #ffffff, #e6edf5) !important;
}
.ov-card__art, .ov-rail__portrait { border-radius: 3px !important; }
.ov-card__tokens { font-family: var(--neon-font-mono); border-radius: 2px; }
/* the auto-hiding top bar slides over Home: keep the greeting below where it lands */
:root[data-overhaul="on"] { --mari-home-hero-padding: calc(var(--mari-top-bar-height, 45px) + 0.5rem) 0.25rem 1rem; }
:is(.ov-card__art, .ov-rail__portrait-empty, .mari-avatar-placeholder) svg { color: var(--nc) !important; opacity: 0.75; }
/* phones and tablets: the conversation log spans the screen, so the veil is even across it */
:root[data-overhaul="mobile"] [data-chat-mode="conversation"]:not([data-mari-part="chat-header"]) { background: rgb(5 6 11 / 0.8) !important; }
:root[data-overhaul="mobile"][data-theme="light"] [data-chat-mode="conversation"]:not([data-mari-part="chat-header"]) { background: rgb(246 248 252 / 0.88) !important; }
/* message menu: ink labels, cyan glyphs, one magenta danger line */
.ov-rpf-menu { border-radius: 3px; border-color: var(--line-strong); background: var(--glass-strong); }
/* (R5N5 fixed in the app: menu labels already take the text colour) */
.ov-rpf-menu .mari-message-actions button[title] svg { color: var(--nc); -webkit-text-fill-color: currentColor; }
.ov-rpf-menu .mari-message-actions > button[title]:last-of-type:has(svg.lucide-trash2, svg.lucide-trash-2) svg { color: inherit; }
.ov-rpf-pop__label { font-family: var(--neon-font-mono); letter-spacing: 0.14em; }
[data-sonner-toast] [data-button] { border-radius: 2px !important; background: transparent !important; color: var(--nc) !important; box-shadow: inset 0 0 0 1px var(--line-strong) !important; font-family: var(--neon-font-mono); }
[data-sonner-toast] [data-close-button] { border-radius: 2px !important; background: var(--glass-strong) !important; color: var(--dim) !important; border-color: var(--line-strong) !important; }
/* conversation rows run edge to edge: brackets there would be clipped by the sidebar, so the log stays flat */
[data-chat-mode="conversation"] [data-mari-part="message"][data-latest], [data-chat-mode="conversation"] [data-mari-part="message"][data-latest] .mari-message-bubble { border-image: none !important; }
/* the persona chip in the message box: a square mono tile like every other avatar */
[data-mari-part="composer"] .rounded-full:has(> img), [data-mari-part="composer"] button.rounded-full.h-8, [data-mari-part="composer"] .h-8.w-8.rounded-full { border-radius: 3px !important; }

/* ═════ v1.5: message tools in mono, VN text box as a terminal pane ═════ */
.ov-rpf__count, [data-mari-part="swipe-counter"] { font-family: var(--neon-font-mono); }
[data-mari-part="vn-counter"] { font-family: var(--neon-font-mono); letter-spacing: 0.08em; color: var(--dim); }
[data-mari-part="vn-nav"] { border-radius: 3px !important; font-family: var(--neon-font-mono); color: var(--nc); }
/* VN: the composer's fade stays off (the VN box is its own glass pane, the city shows above it) */
[data-roleplay-chat-column="true"]:has(.mari-roleplay-vn-dialogue)::before { display: none; }
.mari-roleplay-vn-dialogue [data-mari-part="avatar"] { border-radius: 3px; border-color: var(--line-strong); background: #0b1020; color: var(--nc); }
:root[data-theme="light"] .mari-roleplay-vn-dialogue [data-mari-part="avatar"] { background: #fff; }
.mari-roleplay-vn-dialogue [data-mari-part="header"] {
  font-family: var(--neon-font-mono); font-weight: 400; font-size: 0.82rem; letter-spacing: 0.06em; text-transform: uppercase; color: var(--nc);
}
.mari-roleplay-vn-dialogue [data-mari-part="header"] :is(span, *) { color: inherit !important; -webkit-text-fill-color: currentColor; }
.mari-roleplay-vn-dialogue[data-message-role="user"] [data-mari-part="header"] { color: var(--nm); }
/* the VN pane is the surface with focus: same glass, same brackets */
[data-roleplay-vn] > .mari-chat-style-surface {
  border-radius: 3px; border-color: var(--line-strong); backdrop-filter: blur(8px);
  border-image: var(--mari-focus-frame); border-image-outset: var(--mari-focus-frame-outset);
}
/* phones: an empty VN portrait (no picture) gives its width back to the text; a real portrait stays */
@media (max-width: 767px) {
  .mari-roleplay-vn-dialogue > [data-mari-part="avatar"]:not(:has(img)) { display: none; }
}
/* portrait screens in Game: the corridor's middle is a black void, so frame the lit terminal on the right */
@media (max-aspect-ratio: 4/5) {
  :root[data-theme][data-chat-open-mode="game"] {
    --mari-app-backdrop-layers: linear-gradient(180deg, rgb(5 6 11 / 0.1), rgb(5 6 11 / 0.3)), url("theme:bd-game.webp") 86% 40% / cover no-repeat;
  }
}
/* Game: party initials (now an avatar-placeholder part) are square mono tiles; the narration pane is a terminal window */
.ov-gpane__av[data-mari-part="avatar-placeholder"] {
  border-radius: 3px !important; background: transparent !important; box-shadow: inset 0 0 0 1px var(--line-strong);
  color: var(--nc) !important; font-family: var(--neon-font-mono); font-weight: 400;
}
.ov-gpane__av[data-mari-part="avatar-placeholder"][data-role="user"] { box-shadow: inset 0 0 0 1px rgb(255 43 214 / 0.45); color: var(--nm) !important; }
.mari-game-narration-surface { border-radius: 3px !important; }
.mari-game-narration-surface > .mb-2 > span.rounded-full.uppercase {
  border-radius: 2px; background: transparent; box-shadow: inset 0 0 0 1px rgb(255 181 71 / 0.45);
  color: var(--na); font-family: var(--neon-font-mono); font-weight: 400; letter-spacing: 0.14em;
}
